    while (i <= j) {
      while (array[i] < pivot) i++;
      while (array[j] > pivot) j--;
      if (i <= j) {
        [array[i], array[j]] = [array[j], array[i]];
        i++;
        j--;
      }
    }

    quickSort(array, left, j);
    quickSort(array, i, right);
  };

  const result = [...arr];
  quickSort(result, 0, result.length - 1);
  return result;
}
